const localStorage = window.__tkStore;

const ages=['0–6 meses','6–12 meses','1–2 anos','2–3 anos','4–6 anos','7–9 anos','10–12 anos'],skills=['Sensorial','Motricidade fina','Motricidade global','AVDs','Atenção e cognição','Brincar e interação'],goals=['Exploração e participação','Coordenação e planejamento','Autonomia funcional','Autorregulação e conforto','Atenção e sequenciamento'];
const data=[['Exploração de tecidos',0,1,'Sensorial','Ofereça tecidos grandes de diferentes texturas e permita exploração espontânea.','Observar iniciativa, conforto e preferência.','Não cobrir o rosto; supervisão constante.'],['Alcance funcional',0,1,'Motricidade global','Ofereça brinquedo grande e leve ao alcance, ajustando postura e distância.','Observar alcance e controle postural.','Respeitar controle cervical e fadiga.'],['Cesto de objetos',1,3,'Motricidade fina','Retirar, transferir e recolocar objetos grandes em um cesto.','Observar preensão, coordenação bilateral e iniciativa.','Evitar peças pequenas.'],['Caixa de texturas',2,4,'Sensorial','Apresentar esponjas, tecidos e pincéis macios; criança escolhe explorar com mãos ou ferramentas.','Observar participação e sinais de desconforto.','Não forçar contato.'],['Vestir boneco',2,4,'AVDs','Praticar colocar e retirar roupas largas de um boneco, oferecendo ajuda graduada.','Observar sequência e coordenação bilateral.','Usar materiais seguros.'],['Trilha de almofadas',3,5,'Motricidade global','Montar percurso baixo e estável, com apoio graduado e escolhas.','Observar equilíbrio e planejamento motor.','Evitar altura e quedas.'],['Massinha funcional',3,5,'Motricidade fina','Amassar, rolar e modelar massa apropriada para idade.','Observar força e manipulação.','Verificar risco de ingestão.'],['Sequência de higiene',4,6,'AVDs','Usar cartões para planejar e praticar higiene real com redução gradual de pistas.','Observar independência nas etapas.','Respeitar privacidade e acessibilidade.'],['Circuito de escolhas',4,6,'Sensorial','Oferecer estações de movimento e exploração com opção de pausa e recusa.','Observar preferências e participação.','Não presumir efeito regulatório.'],['Organizar mochila',5,6,'Atenção e cognição','Criar checklist e organizar objetos escolares em sequência funcional.','Observar planejamento e autonomia.','Ajustar demanda à criança.'],['Preparar lanche',5,6,'AVDs','Planejar e executar etapas seguras de preparo de lanche.','Observar sequência e participação.','Checar alergias, deglutição e higiene.'],['Jogo cooperativo',4,6,'Brincar e interação','Construir algo com blocos em turnos e com papéis combinados.','Observar turnos e comunicação.','Usar peças seguras.']];
let state={age:3,skill:'Sensorial',goal:0,duration:30,items:[],saved:JSON.parse(localStorage.getItem('tk_saved')||'[]'),notes:JSON.parse(localStorage.getItem('tk_notes')||'[]'),assess:JSON.parse(localStorage.getItem('tk_assess')||'[]')};const app=document.getElementById('app');function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}function opts(a,v){return a.map((x,i)=>`<option value="${i}" ${i==v?'selected':''}>${x}</option>`).join('')}function persist(){localStorage.setItem('tk_saved',JSON.stringify(state.saved));localStorage.setItem('tk_notes',JSON.stringify(state.notes));localStorage.setItem('tk_assess',JSON.stringify(state.assess))}function cards(items){return items.map((x,i)=>`<div class="activity"><b>${i+1}. ${x[0]}</b><p>${x[4]}</p><small><b>Indicador:</b> ${x[5]}<br><b>Cuidados:</b> ${x[6]}</small></div>`).join('')}
function view(tab){if(tab==='sensory')return renderSensory();if(tab==='dashboard')return renderDashboard();if(tab==='foodprogress')return renderFoodProgress();if(tab==='foodplan')return renderFoodPlan();if(tab==='foodactivities')return renderFoodActivities();if(tab==='feeding')return renderFeeding();if(tab==='advanced')return renderAdvanced();if(tab==='patients')return renderPatients();if(tab==='plan')app.innerHTML=`<section><h2>Planejar sessão</h2><label>Faixa etária</label><select id="age">${opts(ages,state.age)}</select><label>Habilidade</label><select id="skill">${opts(skills,skills.indexOf(state.skill))}</select><label>Objetivo</label><select id="goal">${opts(goals,state.goal)}</select><label>Duração</label><select id="duration">${opts(['20','30','45','60'],['20','30','45','60'].indexOf(String(state.duration)))}</select><p><button onclick="generate()">Gerar roteiro</button></p></section><section id="result">${state.items.length?cards(state.items)+'<button onclick="savePlan()">Salvar roteiro</button>':''}</section>`;
if(tab==='eval')app.innerHTML=`<section><h2>🧒 Avaliação infantil completa • 0 a 12 anos</h2><p class="muted">Registro funcional estruturado. Não substitui instrumentos padronizados, avaliação clínica ou diagnóstico.</p>
<label>Paciente</label><select id="evcode">${patientOptions()}</select>
<label>Data da avaliação</label><input id="evdate" type="date" value="${new Date().toISOString().slice(0,10)}">
<label>Faixa etária</label><select id="evage">${opts(ages,state.age)}</select>
<label>Contexto</label><select id="evcontext">${opts(['Clínica','Casa','Escola','Teleatendimento','Outro'],0)}</select>
<label>Demanda principal e relato da família</label><textarea id="evdemand" placeholder="Queixas, prioridades e participação nas rotinas"></textarea>
<h3>Domínios funcionais</h3><p class="muted">Marque o nível observado em cada domínio. 'Não avaliado' não entra no resumo.</p>
<div id="domainRows">${evalDomains.map((d,i)=>`<div class="activity"><b>${esc(d)}</b><select id="domain${i}">${opts(['Não avaliado','Realiza com autonomia','Realiza com apoio','Dificuldade importante','Não observado no contexto'],0)}</select><textarea id="detail${i}" placeholder="Tarefa observada, facilitadores, barreiras e apoio necessário"></textarea></div>`).join('')}</div>
<h3>Perfil alimentar e sensorial</h3><label>Seletividade alimentar / refeições</label><textarea id="evfood" placeholder="Variedade, texturas, aceitação, participação, segurança e contexto"></textarea>
<label>Adaptações e recursos utilizados</label><textarea id="evadapt" placeholder="Postura, utensílios, pistas, rotina e ambiente"></textarea>
<h3>Plano terapêutico</h3><label>Metas funcionais observáveis</label><textarea id="evgoals" placeholder="O que a criança fará, em qual contexto e com qual nível de apoio"></textarea>
<label>Encaminhamentos e alertas</label><textarea id="evref" placeholder="Ex.: avaliação de deglutição, nutrição, pediatria, se indicado"></textarea>
<p><button onclick="saveFullEval()">Salvar avaliação</button> <button onclick="exportBackup()">Exportar backup JSON</button></p>
<p class="muted">Privacidade: dados ficam neste navegador, sem sincronização ou criptografia. Use códigos anônimos; não inclua nomes completos ou dados sensíveis em dispositivos compartilhados.</p></section>
<section><h3>Avaliações salvas (${fullEvals.length})</h3>${fullEvals.map((x,i)=>`<div class="activity"><b>${esc(x.code||'Sem código')} • ${esc(x.date)} • ${esc(ages[x.age]||'')}</b><p>${esc(x.demand||'Sem demanda informada')}</p><p class="muted">Domínios com registro: ${x.domains.filter(d=>d.status!==0).length}/${evalDomains.length}</p><button onclick="printEval(${i})">Imprimir / PDF</button> <button onclick="deleteEval(${i})">Excluir</button></div>`).join('')||'<p>Nenhuma avaliação registrada.</p>'}</section>`;
if(tab==='library')app.innerHTML=`<section><h2>Biblioteca de atividades</h2><p class="muted">${data.length} atividades demonstrativas</p>${cards(data)}</section>`;
if(tab==='saved')app.innerHTML=`<section><h2>Meus roteiros</h2>${state.saved.map((x,i)=>`<div class="activity"><b>${esc(x.title)}</b>${cards(x.items)}<button onclick="removeSaved(${i})">Excluir</button></div>`).join('')||'Nenhum roteiro salvo.'}</section>`;
if(tab==='notes')app.innerHTML=`<section><h2>Evolução clínica</h2><label>Paciente</label><select id="notePatient">${patientOptions()}</select><p class="muted">Não inclua nomes ou dados identificáveis.</p><textarea id="note" placeholder="Participação, pistas necessárias, resposta, metas para próxima sessão..."></textarea><p><button onclick="saveNote()">Registrar evolução</button></p></section><section>${state.notes.map(x=>`<p>${esc(typeof x==='string'?x:(x.date+' • '+x.code+' — '+x.text))}</p>`).join('')||'Sem registros.'}</section>`;}
function generate(){state.age=+document.getElementById('age').value;state.skill=skills[+document.getElementById('skill').value];state.goal=+document.getElementById('goal').value;state.duration=+[20,30,45,60][+document.getElementById('duration').value];let n=state.duration===20?2:state.duration===30?3:state.duration===45?4:5;state.items=data.filter(x=>state.age>=x[1]&&state.age<=x[2]).sort((a,b)=>Number(b[3]===state.skill)-Number(a[3]===state.skill)).slice(0,n);document.getElementById('result').innerHTML='<h3>Roteiro sugerido</h3><p class="muted">'+ages[state.age]+' • '+state.skill+' • '+state.duration+' minutos. Revise a adequação individual.</p>'+cards(state.items)+'<button onclick="savePlan()">Salvar roteiro</button>'}function savePlan(){state.saved.push({title:ages[state.age]+' • '+state.skill+' • '+state.duration+' min',items:state.items});persist();view('saved')}function removeSaved(i){state.saved.splice(i,1);persist();view('saved')}function saveEval(){let t=document.getElementById('evtext').value.trim();if(!t)return alert('Descreva uma observação.');state.assess.unshift(ages[+document.getElementById('evage').value]+' • '+skills[+document.getElementById('evskill').value]+' • '+['Independente','Com apoio','Ainda não observado','Não avaliado'][+document.getElementById('evstatus').value]+' — '+t);persist();view('eval')}function saveNote(){let t=document.getElementById('note').value.trim();if(!t)return;if(!val('notePatient'))return alert('Cadastre e selecione um paciente.');state.notes.unshift({code:val('notePatient'),date:new Date().toISOString().slice(0,10),text:t});persist();view('notes')}

let patients=[];try{patients=JSON.parse(localStorage.getItem('tk_patients_v3')||'[]')}catch(e){patients=[]}
function patientOptions(){return '<option value="">Selecione um paciente</option>'+patients.map(p=>`<option value="${esc(p.code)}">${esc(p.code)} — ${esc(p.age||'idade não informada')}</option>`).join('')}
function renderPatients(){
app.innerHTML=`<section><h2>Prontuários por paciente</h2><p class="muted">Use somente códigos anônimos. Esta versão é um protótipo local, sem login, criptografia, sincronização ou conformidade de segurança validada para dados identificáveis de saúde.</p>
<label>Código do paciente (sem nome)</label><input id="patCode" placeholder="Ex.: CR-001" maxlength="40">
<label>Faixa etária</label><select id="patAge">${opts(ages,3)}</select>
<label>Prioridade terapêutica</label><textarea id="patPriority" placeholder="Descreva sem informações identificáveis"></textarea>
<button onclick="addPatient()">Cadastrar paciente</button> <button onclick="exportBackup()">Exportar backup</button>
<label>Restaurar backup JSON</label><input type="file" accept=".json,application/json" id="restoreFile"><button onclick="restoreBackup()">Importar backup</button>
</section><section><h3>Pacientes cadastrados (${patients.length})</h3>${patients.map(p=>`<div class="activity"><b>${esc(p.code)}</b> • ${esc(p.age||'')}</p><p>${esc(p.priority||'')}</p><p>${fullEvals.filter(e=>e.code===p.code).length} avaliações • ${state.notes.filter(n=>typeof n==='object'&&n.code===p.code).length} evoluções</p><button onclick="patientDetail('${esc(p.code)}')">Abrir prontuário</button></div>`).join('')||'<p>Nenhum paciente cadastrado.</p>'}</section>`;
}
function addPatient(){let code=val('patCode').trim().toUpperCase();if(!/^[A-Z0-9_-]{2,40}$/.test(code))return alert('Use código anônimo de 2 a 40 caracteres (letras, números, _ ou -).');if(patients.some(p=>p.code===code))return alert('Código já cadastrado.');patients.push({code,age:ages[+val('patAge')],priority:val('patPriority')});localStorage.setItem('tk_patients_v3',JSON.stringify(patients));renderPatients()}
function patientDetail(code){let p=patients.find(x=>x.code===code);if(!p)return;let ev=fullEvals.map((x,i)=>({...x,i})).filter(x=>x.code===code),notes=state.notes.filter(x=>typeof x==='object'&&x.code===code);
app.innerHTML=`<section><button onclick="view('patients')">← Voltar</button><h2>Prontuário ${esc(code)}</h2><p>${esc(p.age)} • ${esc(p.priority)}</p><p><b>${ev.length}</b> avaliações • <b>${notes.length}</b> evoluções</p><button onclick="view('eval')">Nova avaliação</button> <button onclick="view('notes')">Nova evolução</button> <button onclick="view('feeding')">Avaliação alimentar</button> <button onclick="view('foodplan')">Plano alimentar</button><button onclick="view('foodprogress')">Evolução alimentar</button><button onclick="view('dashboard')">Painel terapêutico</button><button onclick="view('sensory')">Desenvolvimento sensoriomotor</button></section><section><h3>Histórico de avaliações</h3>${ev.map(x=>`<div class="activity"><b>${esc(x.date)}</b><p>${esc(x.demand)}</p><button onclick="printEval(${x.i})">Imprimir / PDF</button></div>`).join('')||'Nenhuma avaliação.'}</section><section><h3>Histórico de evoluções</h3>${notes.map(x=>`<div class="activity"><b>${esc(x.date)}</b><p>${esc(x.text)}</p></div>`).join('')||'Nenhuma evolução.'}</section><section><h3>Registros alimentares</h3>${feedingRecords.map((r,i)=>({...r,i})).filter(r=>r.code===code).map(r=>`<div class="activity"><b>${esc(r.date)}</b> • ${r.foods.length} alimentos registrados <button onclick="printFeeding(${r.i})">Imprimir / PDF</button></div>`).join('')||'Nenhum registro alimentar.'}</section>`}
function restoreBackup(){let f=document.getElementById('restoreFile').files[0];if(!f)return alert('Selecione um arquivo JSON.');let r=new FileReader();r.onload=()=>{try{let b=JSON.parse(r.result);if(!Array.isArray(b.patients)||!Array.isArray(b.fullEvals)||!Array.isArray(b.evolucoes))throw Error('Formato incompatível');if(!confirm('A importação substituirá os registros atuais neste navegador. Continue?'))return;patients=b.patients;fullEvals=b.fullEvals;advanced=Array.isArray(b.advanced)?b.advanced:[];feedingRecords=Array.isArray(b.feedingRecords)?b.feedingRecords:[];localStorage.setItem('tk_feeding_v5',JSON.stringify(feedingRecords));localStorage.setItem('tk_advanced_v4',JSON.stringify(advanced));state.notes=b.evolucoes;state.saved=Array.isArray(b.roteiros)?b.roteiros:state.saved;localStorage.setItem('tk_patients_v3',JSON.stringify(patients));localStorage.setItem('tk_full_evals_v2',JSON.stringify(fullEvals));persist();foodPlans=Array.isArray(b.foodPlans)?b.foodPlans:[];localStorage.setItem('tk_foodplans_v52',JSON.stringify(foodPlans));sessionMetrics=Array.isArray(b.sessionMetrics)?b.sessionMetrics:[];localStorage.setItem('tk_session_metrics_v54',JSON.stringify(sessionMetrics));sensoryPlans=Array.isArray(b.sensoryPlans)?b.sensoryPlans:[];localStorage.setItem('tk_sensory_plans_v55',JSON.stringify(sensoryPlans));renderPatients();alert('Backup restaurado.')}catch(e){alert('Não foi possível importar: '+e.message)}};r.readAsText(f)}

const evalDomains=['Participação e brincar','Interação e comunicação funcional','Regulação emocional e sensorial','Processamento tátil e respostas a estímulos','Controle postural e equilíbrio','Coordenação motora grossa','Coordenação motora fina e bilateral','Planejamento motor e práxis','Atenção e funções executivas','Alimentação e participação nas refeições','Vestir-se e despir-se','Higiene e autocuidado','Sono e rotinas','Participação escolar','Participação familiar e comunitária'];
let fullEvals=[];try{fullEvals=JSON.parse(localStorage.getItem('tk_full_evals_v2')||'[]')}catch(e){fullEvals=[]}
function val(id){return document.getElementById(id)?.value||''}
function saveFullEval(){
const x={code:val('evcode').trim(),date:val('evdate'),age:+val('evage'),context:val('evcontext'),demand:val('evdemand'),food:val('evfood'),adapt:val('evadapt'),goals:val('evgoals'),ref:val('evref'),domains:evalDomains.map((name,i)=>({name,status:+val('domain'+i),detail:val('detail'+i)}))};
if(!x.code||!x.date)return alert('Cadastre e selecione um paciente e preencha a data.');
fullEvals.unshift(x);localStorage.setItem('tk_full_evals_v2',JSON.stringify(fullEvals));view('eval')
}
function deleteEval(i){if(!confirm('Excluir esta avaliação?'))return;fullEvals.splice(i,1);localStorage.setItem('tk_full_evals_v2',JSON.stringify(fullEvals));view('eval')}
function downloadFile(name,content,type){let blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function exportBackup(){downloadFile('TO_Kids_PRO_5_9_backup_'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({version:5.9,patients,fullEvals,advanced,feedingRecords,foodPlans,sessionMetrics,sensoryPlans,roteiros:state.saved,evolucoes:state.notes,avaliacoesAntigas:state.assess},null,2),'application/json')}
function printEval(i){const x=fullEvals[i];if(!x)return;let w=window.open('','_blank');if(!w)return alert('Permita pop-ups para imprimir.');
const p=s=>esc(s||'—');w.document.write('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Avaliação TO Kids PRO</title><style>body{font:14px Arial;max-width:800px;margin:35px auto;line-height:1.5}h1{color:#164b4c}section{border-bottom:1px solid #ccc;padding:8px 0}small{color:#555}</style><h1>TO Kids PRO 5.9 • Avaliação funcional</h1><p><b>Código:</b> '+p(x.code)+' | <b>Data:</b> '+p(x.date)+' | <b>Faixa:</b> '+p(ages[x.age])+'</p><section><b>Demanda:</b> '+p(x.demand)+'</section>'+x.domains.map(d=>'<section><b>'+p(d.name)+'</b>: '+p(['Não avaliado','Autonomia','Com apoio','Dificuldade importante','Não observado'][d.status])+'<div>'+p(d.detail)+'</div></section>').join('')+['food','adapt','goals','ref'].map((k,j)=>'<section><b>'+['Alimentação','Adaptações','Metas','Encaminhamentos'][j]+':</b> '+p(x[k])+'</section>').join('')+'<p><small>Registro observacional, não diagnóstico. Profissional responsável: __________________________</small></p></html>');w.document.close();w.focus();setTimeout(()=>w.print(),300)}

const milestones=[
['0–6 meses',['Controle de cabeça conforme idade e contexto','Alcance e exploração visual de objetos','Interação responsiva com cuidador','Participação na alimentação e sinais de fome/saciedade','Tolerância a posicionamentos e manejo']],
['6–12 meses',['Sentar e deslocar-se conforme desenvolvimento individual','Transferir objetos entre mãos','Explorar brinquedos e gestos comunicativos','Participar da introdução alimentar segura','Iniciar participação em rotinas de cuidado']],
['1–2 anos',['Explorar deslocamento e mudanças de posição','Manipular objetos e iniciar uso de utensílios','Participar de brincadeiras funcionais','Colaborar em vestir e higiene','Participar das refeições com apoio']],
['2–3 anos',['Participar de brincadeira simbólica inicial','Manipular materiais de desenho e encaixe','Realizar etapas simples de autocuidado','Participar de transições e rotinas','Ampliar autonomia na alimentação']],
['4–6 anos',['Coordenação bilateral em atividades funcionais','Participação em jogos e brincadeiras compartilhadas','Vestir-se e higiene com apoios graduados','Participar de tarefas pré-escolares','Participar das refeições em diferentes contextos']],
['7–9 anos',['Organizar materiais e rotina escolar','Executar tarefas motoras finas funcionais','Autonomia progressiva em autocuidado','Participação em atividades com pares','Preparar lanche simples com supervisão']],
['10–12 anos',['Planejar e sequenciar rotinas pessoais','Participar de tarefas domésticas adequadas','Gerenciar materiais escolares com estratégias','Preparar refeições simples com supervisão','Identificar necessidades de apoio e autorregulação']]
];
let advanced=[];try{advanced=JSON.parse(localStorage.getItem('tk_advanced_v4')||'[]')}catch(e){advanced=[]}
function renderAdvanced(){app.innerHTML=`<section><h2>Avaliação pediátrica avançada</h2><p class="muted">Roteiro observacional por faixa etária; itens exemplificativos, não constituem escala validada nem diagnóstico de atraso.</p>
<label>Paciente</label><select id="advPatient">${patientOptions()}</select><label>Data</label><input id="advDate" type="date" value="${new Date().toISOString().slice(0,10)}"><label>Faixa etária</label><select id="advAge" onchange="renderMilestones()">${opts(ages,3)}</select><div id="advMilestones"></div>
<label>AVDs: alimentação, higiene, vestuário e banheiro</label><textarea id="advAvd" placeholder="Descreva desempenho real, apoio e contexto"></textarea><label>Perfil sensorial e autorregulação</label><textarea id="advSens" placeholder="Respostas observadas, facilitadores, barreiras"></textarea><label>Brincar, escola e participação social</label><textarea id="advParticipation"></textarea><label>Seletividade alimentar</label><textarea id="advFood" placeholder="Alimentos aceitos, textura, ambiente, sinais de segurança e participação"></textarea><label>Metas funcionais e reavaliação</label><textarea id="advGoals" placeholder="Meta, contexto, frequência, nível de apoio e prazo"></textarea><button onclick="saveAdvanced()">Salvar avaliação avançada</button></section>
<section><h3>Histórico (${advanced.length})</h3>${advanced.map((a,i)=>`<div class="activity"><b>${esc(a.code)} • ${esc(a.date)} • ${esc(ages[a.age])}</b><p>${a.items.filter(x=>x.status==='observado').length} itens observados; ${a.items.filter(x=>x.status==='apoio').length} com apoio; ${a.items.filter(x=>x.status==='dificuldade').length} com dificuldade.</p><button onclick="printAdvanced(${i})">Imprimir / PDF</button></div>`).join('')||'<p>Nenhum registro.</p>'}</section>`;renderMilestones()}
function renderMilestones(){let age=+val('advAge');document.getElementById('advMilestones').innerHTML='<h3>Observação funcional: '+esc(ages[age])+'</h3>'+milestones[age][1].map((m,i)=>`<div class="activity"><b>${esc(m)}</b><select id="advItem${i}"><option value="nao">Não avaliado</option><option value="observado">Observado no contexto</option><option value="apoio">Realiza com apoio</option><option value="dificuldade">Dificuldade observada</option></select><textarea id="advDetail${i}" placeholder="Evidência observada e contexto"></textarea></div>`).join('')}
function saveAdvanced(){let code=val('advPatient'),date=val('advDate'),age=+val('advAge');if(!code||!date)return alert('Selecione paciente e data.');let x={code,date,age,items:milestones[age][1].map((name,i)=>({name,status:val('advItem'+i),detail:val('advDetail'+i)})),avd:val('advAvd'),sens:val('advSens'),participation:val('advParticipation'),food:val('advFood'),goals:val('advGoals')};advanced.unshift(x);localStorage.setItem('tk_advanced_v4',JSON.stringify(advanced));renderAdvanced()}
function printAdvanced(i){let x=advanced[i],w=window.open('','_blank');if(!w)return alert('Permita pop-ups');let p=v=>esc(v||'—');w.document.write('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Avaliação avançada</title><style>body{font:14px Arial;max-width:800px;margin:35px auto;line-height:1.5}section{padding:10px 0;border-bottom:1px solid #ccc}</style><h1>TO Kids PRO 5.9 — Avaliação avançada</h1><p>Código: '+p(x.code)+' | Data: '+p(x.date)+' | Faixa: '+p(ages[x.age])+'</p>'+x.items.map(a=>'<section><b>'+p(a.name)+'</b> — '+p(a.status)+'<p>'+p(a.detail)+'</p></section>').join('')+[['AVDs',x.avd],['Sensorial',x.sens],['Participação',x.participation],['Alimentação',x.food],['Metas',x.goals]].map(a=>'<section><b>'+a[0]+'</b><p>'+p(a[1])+'</p></section>').join('')+'<p>Roteiro observacional, não instrumento padronizado. Responsável: ___________________</p>');w.document.close();w.focus();setTimeout(()=>w.print(),300)}


const foodCatalog={
'Frutas':['Banana','Maçã','Pera','Mamão','Melancia','Melão','Manga','Morango','Uva','Laranja','Abacate'],
'Verduras e legumes':['Cenoura','Brócolis','Abobrinha','Abóbora','Batata','Batata-doce','Tomate','Alface','Beterraba','Chuchu'],
'Cereais e tubérculos':['Arroz','Macarrão','Pão','Aveia','Milho','Mandioca','Cuscuz','Tapioca'],
'Leguminosas':['Feijão','Lentilha','Grão-de-bico','Ervilha'],
'Proteínas':['Ovo','Frango','Carne bovina','Peixe','Tofu'],
'Laticínios e alternativas':['Leite','Iogurte','Queijo','Bebida vegetal'],
'Outros':['Biscoito','Sopa','Purê','Panqueca']
};
const foodStatus=['Não avaliado','Aceita habitualmente','Aceita às vezes','Recusa','Não oferecido'];
let feedingRecords=[];try{feedingRecords=JSON.parse(localStorage.getItem('tk_feeding_v5')||'[]')}catch(e){feedingRecords=[]}
let selectedFoods={};
function renderFeeding(){
selectedFoods={};
app.innerHTML=`<section><h2>Seletividade alimentar • 0 a 12 anos</h2><p class="muted">Registro clínico observacional, não instrumento padronizado. Avalie segurança alimentar e causas clínicas antes de intervir. Use somente códigos anônimos.</p>
<label>Paciente</label><select id="feedPatient">${patientOptions()}</select>
<label>Data</label><input id="feedDate" type="date" value="${new Date().toISOString().slice(0,10)}">
<label>Histórico alimentar e prioridades familiares</label><textarea id="feedHistory" placeholder="Rotina, contexto, crescimento acompanhado pela equipe, dificuldades relatadas"></textarea>
<label>Texturas e características relevantes</label><textarea id="feedTexture" placeholder="Crocante, pastoso, misturado, temperatura, cheiro, apresentação"></textarea>
<label>Participação nas refeições e fatores ambientais</label><textarea id="feedContext"></textarea>
<label>Sinais de alerta e encaminhamentos</label><textarea id="feedRisk" placeholder="Tosse/engasgos, perda de peso, dor, vômitos, desidratação; encaminhar conforme indicação"></textarea>
<h3>Lista de alimentos por categoria</h3><p class="muted">Marque a resposta alimentar relatada ou observada. Não oferecido não equivale a recusa.</p>
${Object.entries(foodCatalog).map(([category,items])=>`<details><summary><b>${esc(category)}</b> (${items.length})</summary>${items.map(name=>foodEntry(name,category)).join('')}</details>`).join('')}
<h3>Adicionar alimento manualmente</h3><label>Nome do alimento</label><input id="customFood" maxlength="80" placeholder="Ex.: mingau de aveia">
<label>Categoria</label><select id="customCategory">${Object.keys(foodCatalog).map(c=>`<option>${esc(c)}</option>`).join('')}<option>Outro</option></select>
<button onclick="addCustomFood()">Adicionar à avaliação</button><div id="customFoodList"></div>
<h3>Metas e acompanhamento</h3><label>Meta funcional mensurável</label><textarea id="feedGoal" placeholder="Ex.: participar da refeição por 10 minutos com suporte acordado, sem sofrimento intenso"></textarea>
<label>Estratégias e orientações à família</label><textarea id="feedPlan" placeholder="Exposição gradual sem coerção, modelagem, orientação parental, ajustes funcionais conforme avaliação"></textarea>
<button onclick="saveFeeding()">Salvar avaliação alimentar</button></section>
<section><h3>Histórico alimentar (${feedingRecords.length})</h3>${feedingRecords.map((r,i)=>`<div class="activity"><b>${esc(r.code)} • ${esc(r.date)}</b><p>${r.foods.filter(f=>f.status==='Aceita habitualmente').length} aceitos habitualmente; ${r.foods.filter(f=>f.status==='Recusa').length} recusados; ${r.foods.length} registrados</p><button onclick="printFeeding(${i})">Imprimir / PDF</button></div>`).join('')||'<p>Nenhuma avaliação alimentar salva.</p>'}</section>`;
}
function foodEntry(name,category){let id='food_'+Object.keys(selectedFoods).length;selectedFoods[id]={name,category};return `<div class="activity"><b>${esc(name)}</b><select id="${id}">${foodStatus.map(v=>`<option>${esc(v)}</option>`).join('')}</select></div>`}
function addCustomFood(){let name=val('customFood').trim(),category=val('customCategory');if(!name)return alert('Digite um alimento.');if(Object.values(selectedFoods).some(f=>f.name.toLowerCase()===name.toLowerCase()))return alert('Alimento já está na lista.');let html=foodEntry(name,category);document.getElementById('customFoodList').insertAdjacentHTML('beforeend',html);document.getElementById('customFood').value=''}
function saveFeeding(){let code=val('feedPatient'),date=val('feedDate');if(!code||!date)return alert('Selecione paciente e data.');let foods=Object.entries(selectedFoods).map(([id,f])=>({...f,status:val(id)})).filter(f=>f.status!=='Não avaliado');let r={code,date,foods,history:val('feedHistory'),texture:val('feedTexture'),context:val('feedContext'),risk:val('feedRisk'),goal:val('feedGoal'),plan:val('feedPlan')};feedingRecords.unshift(r);localStorage.setItem('tk_feeding_v5',JSON.stringify(feedingRecords));renderFeeding();alert('Avaliação alimentar salva.')}
function printFeeding(i){let r=feedingRecords[i];if(!r)return;let w=window.open('','_blank');if(!w)return alert('Permita pop-ups para imprimir.');let p=x=>esc(x||'—');w.document.write('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Avaliação alimentar</title><style>body{font:14px Arial;max-width:800px;margin:35px auto;line-height:1.5}section{padding:8px 0;border-bottom:1px solid #ccc}h1{color:#164b4c}</style><h1>TO Kids PRO 5.9 • Avaliação alimentar</h1><p>Paciente: '+p(r.code)+' | Data: '+p(r.date)+'</p>'+[['Histórico',r.history],['Texturas',r.texture],['Participação',r.context],['Alertas',r.risk],['Metas',r.goal],['Estratégias',r.plan]].map(a=>'<section><b>'+a[0]+'</b><p>'+p(a[1])+'</p></section>').join('')+'<h2>Repertório alimentar</h2>'+r.foods.map(f=>'<section>'+p(f.category)+' — <b>'+p(f.name)+'</b>: '+p(f.status)+'</section>').join('')+'<p>Registro observacional, não diagnóstico. Responsável: ___________________</p></html>');w.document.close();w.focus();setTimeout(()=>w.print(),300)}


// Recomendações por regras transparentes: não são decisão clínica automatizada.
let foodPlans=[];try{foodPlans=JSON.parse(localStorage.getItem('tk_foodplans_v52')||'[]')}catch(e){foodPlans=[]}
let foodPlanChoices=[];
const foodPlanGoals=['Ampliar repertório alimentar','Participar das refeições','Explorar características sensoriais','Aumentar autonomia no preparo','Organizar rotina familiar','Ajustar postura e utensílios'];
function foodPlanSuggestions(goal,ageIndex,latest){
 let byGoal={
  'Ampliar repertório alimentar':[0,3,10],
  'Participar das refeições':[1,2,6,11],
  'Explorar características sensoriais':[0,5,4],
  'Aumentar autonomia no preparo':[4,9,6],
  'Organizar rotina familiar':[2,10,11],
  'Ajustar postura e utensílios':[7,8,11]
 };
 let picks=(byGoal[goal]||[0,2,11]).filter(i=>ageIndex>=2||![3,4,9].includes(i));
 if(ageIndex<=1)picks=[2,7,10,11];
 if(latest&&latest.risk&&/engasg|tosse|degluti|aspira|perda de peso|desidrat/i.test(latest.risk))picks=[10,11];
 return picks;
}
function renderFoodPlan(){
let options=patients.map(p=>`<option value="${esc(p.code)}">${esc(p.code)}</option>`).join('');
app.innerHTML=`<section><h2>Plano Terapêutico Alimentar Individualizado</h2><p class="muted">Sugestões baseadas em regras simples e objetivos funcionais, NÃO em diagnóstico, IA clínica ou prescrição automática. O terapeuta revisa e decide. Antes de intervenções, verificar sinais de risco.</p>
<label>Paciente fictício</label><select id="fpPatient" onchange="refreshFoodPlan()"><option value="">Selecione</option>${options}</select>
<label>Objetivo principal</label><select id="fpGoal" onchange="refreshFoodPlan()">${foodPlanGoals.map(g=>`<option>${esc(g)}</option>`).join('')}</select>
<div id="fpSummary"></div><div id="fpChoices"></div>
<label>Meta mensurável (tarefa, contexto, apoio e prazo)</label><textarea id="fpTarget" placeholder="Ex.: participar do preparo de lanche 2 vezes/semana, com apoio verbal, por 4 semanas"></textarea>
<label>Frequência planejada</label><input id="fpFrequency" placeholder="Ex.: 1 sessão semanal + rotina familiar acordada">
<label>Critérios de reavaliação</label><textarea id="fpMeasure" placeholder="Ex.: alimentos consumidos em 3 ocasiões distintas; participação, desconforto e relato familiar"></textarea>
<label>Justificativa clínica e adaptações</label><textarea id="fpRationale" placeholder="Por que essas atividades são adequadas para este paciente?"></textarea>
<button onclick="saveFoodPlan()">Salvar plano aprovado pelo TO</button></section>
<section><h3>Planos salvos (${foodPlans.length})</h3>${foodPlans.map((p,i)=>`<div class="activity"><b>${esc(p.code)} • ${esc(p.date)}</b><p>${esc(p.goal)} • ${p.activities.length} atividades</p><button onclick="printFoodPlan(${i})">Imprimir / PDF</button></div>`).join('')||'Nenhum plano salvo.'}</section>`;
refreshFoodPlan();
}
function refreshFoodPlan(){
let code=val('fpPatient'),goal=val('fpGoal'),pat=patients.find(p=>p.code===code);
let latest=feedingRecords.find(r=>r.code===code);
let ageIndex=pat?ages.indexOf(pat.age):-1;
let summary=document.getElementById('fpSummary'),choices=document.getElementById('fpChoices');
if(!code){summary.innerHTML='<p class="muted">Selecione um paciente para visualizar sugestões.</p>';choices.innerHTML='';return}
let accepted=latest?latest.foods.filter(f=>f.status==='Aceita habitualmente').length:0;
let refused=latest?latest.foods.filter(f=>f.status==='Recusa').length:0;
summary.innerHTML=`<p class="muted">Faixa cadastrada: ${esc(pat.age)}. ${latest?`Última avaliação alimentar: ${esc(latest.date)}; ${accepted} alimentos marcados como aceitos e ${refused} como recusados (somente itens registrados).`:'Sem avaliação alimentar anterior: registre uma linha de base antes de concluir o plano.'}</p>`;
let indices=foodPlanSuggestions(goal,ageIndex,latest);
foodPlanChoices=indices;
choices.innerHTML=`<h3>Atividades sugeridas para revisão</h3>${indices.map(i=>`<div class="activity"><label><input type="checkbox" id="fpAct${i}" checked style="width:auto"> ${esc(foodTherapyActivities[i][0])}</label><p class="muted">${esc(foodTherapyActivities[i][2])}</p><p>${esc(foodTherapyActivities[i][5])}</p></div>`).join('')}<p class="muted">As sugestões não substituem avaliação clínica. Em sinais de risco, interrompa propostas de exposição e encaminhe para avaliação especializada.</p>`;
}
function saveFoodPlan(){
let code=val('fpPatient'),goal=val('fpGoal'),target=val('fpTarget').trim();
if(!code||!target)return alert('Selecione o paciente e preencha uma meta mensurável.');
let activities=foodPlanChoices.filter(i=>document.getElementById('fpAct'+i)?.checked).map(i=>({title:foodTherapyActivities[i][0],evidence:foodTherapyActivities[i][2],steps:foodTherapyActivities[i][5]}));
if(!activities.length)return alert('Selecione ao menos uma atividade.');
let r={code,goal,target,activities,frequency:val('fpFrequency'),measure:val('fpMeasure'),rationale:val('fpRationale'),date:new Date().toISOString().slice(0,10)};
foodPlans.unshift(r);localStorage.setItem('tk_foodplans_v52',JSON.stringify(foodPlans));renderFoodPlan();alert('Plano salvo. Reavalie os resultados periodicamente.');
}
function printFoodPlan(i){
let r=foodPlans[i];if(!r)return;let w=window.open('','_blank');if(!w)return alert('Permita pop-ups.');
w.document.write('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Plano alimentar</title><style>body{font:14px Arial;max-width:800px;margin:35px auto;line-height:1.5}h1{color:#164b4c}section{border-bottom:1px solid #ccc;padding:9px 0}</style><h1>TO Kids PRO 5.9 — Plano alimentar</h1><p>Paciente: '+esc(r.code)+' | '+esc(r.date)+'</p><section><b>Objetivo:</b> '+esc(r.goal)+'</section><section><b>Meta:</b> '+esc(r.target)+'</section><section><b>Frequência:</b> '+esc(r.frequency)+'</section><section><b>Reavaliação:</b> '+esc(r.measure)+'</section><section><b>Justificativa:</b> '+esc(r.rationale)+'</section><h2>Atividades aprovadas</h2>'+r.activities.map(a=>'<section><b>'+esc(a.title)+'</b><p>'+esc(a.steps)+'</p><small>Evidência: '+esc(a.evidence)+'</small></section>').join('')+'<p>Registro de planejamento, não diagnóstico. Profissional: __________________</p></html>');w.document.close();w.focus();setTimeout(()=>w.print(),300)
}


// Comparação longitudinal descritiva, somente entre itens equivalentes avaliados nas duas datas.
function foodMap(record){let m=new Map();for(let f of record.foods||[]){let k=String(f.name||'').trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();if(k)m.set(k,f)}return m}
function renderFoodProgress(){
let options=patients.map(p=>`<option value="${esc(p.code)}">${esc(p.code)}</option>`).join('');
app.innerHTML=`<section><h2>Evolução Alimentar • comparação entre avaliações</h2><p class="muted">Análise descritiva por alimento, não teste padronizado nem prova de eficácia terapêutica. Apenas alimentos registrados em ambas as avaliações são comparáveis.</p><label>Paciente fictício</label><select id="prPatient" onchange="refreshFoodProgress()"><option value="">Selecione</option>${options}</select><div id="prSelects"></div><div id="prResults"></div></section>`;
}
function refreshFoodProgress(){let code=val('prPatient'),records=feedingRecords.map((r,i)=>({...r,idx:i})).filter(r=>r.code===code).sort((a,b)=>a.date.localeCompare(b.date)||b.idx-a.idx),el=document.getElementById('prSelects');document.getElementById('prResults').innerHTML='';if(records.length<2){el.innerHTML='<p class="muted">É necessário ter pelo menos duas avaliações alimentares do mesmo paciente.</p>';return}
let opts=records.map((r,j)=>`<option value="${r.idx}">${esc(r.date)} — avaliação ${j+1} (${r.foods.length} alimentos)</option>`).join('');el.innerHTML=`<label>Avaliação inicial</label><select id="prBefore">${opts}</select><label>Avaliação posterior</label><select id="prAfter">${opts}</select><p><button onclick="compareFoodProgress()">Comparar avaliações</button></p>`;
document.getElementById('prBefore').value=String(records[records.length-1].idx);document.getElementById('prAfter').value=String(records[0].idx);
}
let lastProgress=null;
function compareFoodProgress(){let a=feedingRecords[+val('prBefore')],b=feedingRecords[+val('prAfter')];if(!a||!b||a===b)return alert('Selecione duas avaliações diferentes.');if(a.date>b.date)return alert('A avaliação inicial deve ter data anterior ou igual à posterior.');let old=foodMap(a),now=foodMap(b),common=[];for(let [k,f] of old){if(now.has(k))common.push({name:f.name,from:f.status,to:now.get(k).status})}
let rank={'Recusa':0,'Aceita às vezes':1,'Aceita habitualmente':2};let up=0,down=0,same=0,unknown=0;for(let r of common){if(!(r.from in rank)||!(r.to in rank)){unknown++;continue}if(rank[r.to]>rank[r.from])up++;else if(rank[r.to]<rank[r.from])down++;else same++}
let newly=[...now].filter(([k])=>!old.has(k)).map(([,v])=>v.name),missing=[...old].filter(([k])=>!now.has(k)).map(([,v])=>v.name);
lastProgress={a,b,common,up,down,same,unknown,newly,missing};
document.getElementById('prResults').innerHTML=`<h3>Comparação: ${esc(a.date)} → ${esc(b.date)}</h3><p><b>${common.length}</b> alimentos em comum: ${up} mudança para categoria de maior aceitação; ${down} para menor; ${same} sem mudança; ${unknown} sem comparação ordinal.</p><p class="muted">A categoria “Não oferecido” não equivale a recusa e não entra na contagem de mudança. Mudanças registradas não demonstram consumo, generalização nem causalidade da intervenção.</p><div style="overflow:auto"><table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left">Alimento</th><th>Antes</th><th>Depois</th></tr></thead><tbody>${common.map(r=>`<tr><td style="border-bottom:1px solid #ddd;padding:8px">${esc(r.name)}</td><td style="border-bottom:1px solid #ddd;padding:8px">${esc(r.from)}</td><td style="border-bottom:1px solid #ddd;padding:8px">${esc(r.to)}</td></tr>`).join('')}</tbody></table></div><p class="muted">Só na avaliação posterior: ${newly.length?newly.map(esc).join(', '):'nenhum'}. Só na inicial: ${missing.length?missing.map(esc).join(', '):'nenhum'}.</p><p><button onclick="printFoodProgress()">Imprimir comparação / PDF</button></p>`;
}
function printFoodProgress(){if(!lastProgress)return;let {a,b,common,up,down,same,unknown,newly,missing}=lastProgress;let w=window.open('','_blank');if(!w)return alert('Permita pop-ups para imprimir.');w.document.write('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Evolução alimentar</title><style>body{font:14px Arial;max-width:850px;margin:35px auto;line-height:1.5}h1{color:#164b4c}td,th{border-bottom:1px solid #ccc;padding:8px;text-align:left}table{width:100%;border-collapse:collapse}</style><h1>TO Kids PRO 5.9 — Evolução Alimentar</h1><p>Código: '+esc(a.code)+' | Inicial: '+esc(a.date)+' | Posterior: '+esc(b.date)+'</p><p>Comparáveis: '+common.length+'; maior aceitação: '+up+'; menor: '+down+'; iguais: '+same+'; não classificáveis: '+unknown+'.</p><table><tr><th>Alimento</th><th>Antes</th><th>Depois</th></tr>'+common.map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+esc(r.from)+'</td><td>'+esc(r.to)+'</td></tr>').join('')+'</table><p>Somente na posterior: '+esc(newly.join(', ')||'nenhum')+'. Somente na inicial: '+esc(missing.join(', ')||'nenhum')+'.</p><p>Comparação descritiva. Não demonstra causalidade, ingestão efetiva ou eficácia terapêutica.</p><p>Terapeuta responsável: ___________________</p></html>');w.document.close();w.focus();setTimeout(()=>w.print(),300)}


let sessionMetrics=[];try{sessionMetrics=JSON.parse(localStorage.getItem('tk_session_metrics_v54')||'[]')}catch(e){sessionMetrics=[]}
const metricLabels={exploration:'Exploração sensorial voluntária',participation:'Participação na atividade/refeição',goal:'Meta terapêutica observada'};
function renderDashboard(){
let optsP=patients.map(p=>`<option value="${esc(p.code)}">${esc(p.code)}</option>`).join('');
app.innerHTML=`<section><h2>Painel de evolução terapêutica</h2><p class="muted">Indicadores descritivos dos registros. Não são escalas clínicas validadas nem demonstram causalidade terapêutica.</p><label>Paciente fictício</label><select id="dashPatient" onchange="refreshDashboard()"><option value="">Selecione</option>${optsP}</select><div id="dashResults"></div></section><section><h3>Registrar observação de sessão</h3><p class="muted">Use a mesma escala operacional em sessões sucessivas. Registre apenas comportamentos observáveis, sem inferir aceitação por simples contato.</p><label>Data</label><input id="metricDate" type="date" value="${new Date().toISOString().slice(0,10)}"><label>Indicador</label><select id="metricType">${Object.entries(metricLabels).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select><label>Nível observado</label><select id="metricLevel"><option value="0">0 — Não ocorreu</option><option value="1">1 — Ocorreu com apoio intenso</option><option value="2">2 — Ocorreu com apoio parcial</option><option value="3">3 — Ocorreu com apoio mínimo/independente</option></select><label>Contexto, tarefa e apoio oferecido</label><textarea id="metricContext" placeholder="Ex.: explorou alimento com utensílio durante 2 minutos; apoio verbal"></textarea><button onclick="saveSessionMetric()">Salvar observação</button></section>`;
refreshDashboard();}
function metricBars(records,fn){return `<div class="bars">${records.map((r,i)=>{let n=fn(r);return `<div class="barcol"><div class="bar" style="height:${Math.max(2,n*25)}px" title="${n} alimentos"></div><div class="barlabel">${esc(r.date)}<br>${n}</div></div>`}).join('')}</div>`}
function refreshDashboard(){let code=val('dashPatient'),box=document.getElementById('dashResults');if(!code){box.innerHTML='<p class="muted">Escolha um paciente para consultar o painel.</p>';return}
let rec=feedingRecords.filter(r=>r.code===code).slice().sort((a,b)=>a.date.localeCompare(b.date));let logs=sessionMetrics.filter(r=>r.code===code).slice().sort((a,b)=>a.date.localeCompare(b.date));let plans=foodPlans.filter(r=>r.code===code);let last=rec[rec.length-1];let accepted=last?(last.foods||[]).filter(f=>f.status==='Aceita habitualmente').length:0;
let common=rec.length>1?Array.from(foodMap(rec[0]).keys()).filter(k=>rec.every(r=>foodMap(r).has(k))):[];
box.innerHTML=`<div class="metricgrid"><div class="metric"><b>${rec.length}</b><div>Avaliações alimentares</div></div><div class="metric"><b>${accepted}</b><div>Itens aceitos habitualmente na última avaliação</div></div><div class="metric"><b>${logs.length}</b><div>Observações de sessão</div></div><div class="metric"><b>${plans.length}</b><div>Planos alimentares</div></div></div>
<h3>Repertório alimentar registrado</h3>${rec.length?`<p class="muted">Cada coluna representa o número de alimentos classificados na avaliação; a lista de alimentos pode variar entre datas. Não interprete a altura como mudança clínica sem verificar os itens comuns.</p><b>Aceitos habitualmente</b>${metricBars(rec,r=>(r.foods||[]).filter(f=>f.status==='Aceita habitualmente').length)}<b>Aceitos às vezes</b>${metricBars(rec,r=>(r.foods||[]).filter(f=>f.status==='Aceita às vezes').length)}<b>Recusados</b>${metricBars(rec,r=>(r.foods||[]).filter(f=>f.status==='Recusa').length)}`:'<p>Sem avaliações alimentares registradas.</p>'}
${rec.length>1?`<p class="alert">Itens presentes em todas as ${rec.length} avaliações: <b>${common.length}</b>. Comparações longitudinais confiáveis devem considerar apenas os mesmos alimentos, com condições de observação comparáveis.</p>`:''}
<h3>Participação e exploração — registros de sessão</h3>${Object.entries(metricLabels).map(([type,title])=>{let list=logs.filter(r=>r.type===type);return `<div class="activity"><b>${esc(title)}</b>${list.length?`<div class="bars">${list.map(r=>`<div class="barcol"><div class="bar" style="height:${Math.max(2,(r.level+1)*24)}px" title="Nível ${r.level}"></div><div class="barlabel">${esc(r.date)}<br>${r.level}/3</div></div>`).join('')}</div>`:'<p class="muted">Sem registros deste indicador.</p>'}</div>`}).join('')}
<h3>Histórico de observações</h3>${logs.slice().reverse().map(r=>`<div class="activity"><b>${esc(r.date)} • ${esc(metricLabels[r.type]||r.type)}: ${r.level}/3</b><p>${esc(r.context)}</p></div>`).join('')||'<p class="muted">Nenhuma observação salva.</p>'}
<button onclick="printDashboard()">Imprimir painel / PDF</button>`;}
function saveSessionMetric(){let code=val('dashPatient'),date=val('metricDate'),type=val('metricType'),level=Number(val('metricLevel')),context=val('metricContext').trim();if(!code||!date||!context)return alert('Selecione paciente, data e descreva a observação.');sessionMetrics.push({code,date,type,level,context});localStorage.setItem('tk_session_metrics_v54',JSON.stringify(sessionMetrics));renderDashboard();document.getElementById('dashPatient').value=code;refreshDashboard();alert('Observação salva.');}
function printDashboard(){let code=val('dashPatient');if(!code)return alert('Selecione um paciente.');let rec=feedingRecords.filter(r=>r.code===code).slice().sort((a,b)=>a.date.localeCompare(b.date));let logs=sessionMetrics.filter(r=>r.code===code).slice().sort((a,b)=>a.date.localeCompare(b.date));let w=window.open('','_blank');if(!w)return alert('Permita pop-ups para gerar o PDF.');let html=`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Painel terapêutico</title><style>body{font:14px Arial;max-width:820px;margin:30px auto;line-height:1.5}table{border-collapse:collapse;width:100%}td,th{padding:7px;border:1px solid #ccc;text-align:left}h1{color:#164b4c}</style><h1>TO Kids PRO 5.9 — Painel terapêutico</h1><p>Paciente fictício: ${esc(code)} | Emissão: ${new Date().toLocaleDateString('pt-BR')}</p><h2>Avaliações alimentares</h2><table><tr><th>Data</th><th>Aceita habitualmente</th><th>Aceita às vezes</th><th>Recusa</th></tr>${rec.map(r=>`<tr><td>${esc(r.date)}</td>${['Aceita habitualmente','Aceita às vezes','Recusa'].map(t=>`<td>${(r.foods||[]).filter(f=>f.status===t).length}</td>`).join('')}</tr>`).join('')}</table><h2>Observações de sessão</h2><table><tr><th>Data</th><th>Indicador</th><th>Nível (0–3)</th><th>Contexto</th></tr>${logs.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(metricLabels[r.type]||r.type)}</td><td>${r.level}</td><td>${esc(r.context)}</td></tr>`).join('')}</table><p>Indicadores descritivos. As avaliações podem abranger listas diferentes de alimentos. Os níveis de observação não são escala clínica validada. Não é possível inferir causalidade.</p><p>Profissional: ______________________________</p></html>`;w.document.write(html);w.document.close();w.focus();setTimeout(()=>w.print(),300)}




const sensorySpecific={"0": {"title": "Rastreamento visual", "prep": "Posicione o bebê acordado e apoiado, com o rosto do cuidador visível.", "do": "Apresente cartão de contraste a distância confortável; mova lentamente para um lado e aguarde.", "finish": "Interrompa quando desviar o olhar ou demonstrar cansaço.", "measure": "Registre orientação do olhar e tempo confortável.", "image": "ilustracoes/sensoriais/atividade-000.svg"}, "3": {"title": "Exploração tátil suave", "prep": "Separe algodão, tecido macio e toalha, todos limpos e grandes.", "do": "Mostre primeiro no próprio braço e ofereça escolha entre olhar, tocar com mão ou ferramenta.", "finish": "Troque a textura somente se houver interesse; finalize com a preferida.", "measure": "Registre textura escolhida e iniciativa de contato.", "image": "ilustracoes/sensoriais/atividade-003.svg"}, "6": {"title": "Cesto sensorial seguro", "prep": "Monte cesto com três objetos grandes, laváveis e sem peças soltas.", "do": "Ofereça um objeto por vez para observar, pegar ou explorar com a boca quando apropriado e seguro.", "finish": "Permita repetição e troca espontânea; nomeie ações.", "measure": "Registre objetos explorados e modo de exploração.", "image": "ilustracoes/sensoriais/atividade-006.svg"}, "10": {"title": "Exploração de massa segura", "prep": "Disponha massa atóxica apropriada à idade e rolinho.", "do": "Modele apertar a massa com rolinho; ofereça ferramenta para evitar contato direto.", "finish": "Convide a fazer marcas ou bolinhas, sem insistir se houver recusa.", "measure": "Registre escolha de ferramenta e tempo de engajamento.", "image": "ilustracoes/sensoriais/atividade-010.svg"}, "14": {"title": "Pintura com alternativas", "prep": "Cubra a mesa e disponha tinta lavável, pincel e esponja.", "do": "Demonstre uma marca com pincel e ofereça esponja ou rolinho.", "finish": "Deixe a criança escolher ferramenta e cores; faça pausas conforme necessário.", "measure": "Registre escolhas, ajuda e participação sem coerção.", "image": "ilustracoes/sensoriais/atividade-014.svg"}, "18": {"title": "Escolhas de autorregulação", "prep": "Apresente cartões de pausa, movimento leve e atividade tranquila.", "do": "Convide a criança a apontar qual estratégia quer experimentar em momento neutro.", "finish": "Teste por curto período e pergunte ou observe se ajudou.", "measure": "Registre estratégia escolhida e resposta, sem supor eficácia universal.", "image": "ilustracoes/sensoriais/atividade-018.svg"}, "21": {"title": "Mapa pessoal de conforto", "prep": "Separe cartões de locais e escala visual confortável/desconfortável.", "do": "Peça que a criança identifique um ambiente em que se sente bem e um que exige ajustes.", "finish": "Planejem juntos uma mudança concreta, como reduzir ruído ou pedir pausa.", "measure": "Registre preferência declarada e adaptação testada.", "image": "ilustracoes/sensoriais/atividade-021.svg"}, "26": {"title": "Plano de autorregulação pessoal", "prep": "Liste situações difíceis e estratégias que a própria criança considera úteis.", "do": "Monte cartão com sinais de necessidade, pedido de ajuda e duas opções de apoio.", "finish": "Ensaie uso em situação calma e revise após uso real.", "measure": "Registre se solicitou apoio e o resultado percebido.", "image": "ilustracoes/sensoriais/atividade-026.svg"}, "29": {"title": "Localização de voz familiar", "prep": "Deixe o bebê acordado, confortável e apoiado.", "do": "Cuidador fala em volume natural de um lado, aguarda e depois muda de posição.", "finish": "Observe atenção ou movimento espontâneo, sem solicitar resposta repetidamente.", "measure": "Registre orientação à voz e sinais de conforto.", "image": "ilustracoes/sensoriais/atividade-029.svg"}, "33": {"title": "Pausas de estímulos", "prep": "Organize ambiente com poucos objetos e possibilidade de diminuir luz e som.", "do": "Intercale breves interações com pausas, observando sinais do bebê.", "finish": "Retome somente quando demonstrar disponibilidade.", "measure": "Registre duração tolerada e sinais que antecedem a pausa.", "image": "ilustracoes/sensoriais/atividade-033.svg"}, "36": {"title": "Contrastes no ambiente", "prep": "Selecione um cartão de contraste e fundo visual simples.", "do": "Apresente o cartão parado e permita tempo de observação.", "finish": "Mude posição lentamente se houver interesse; encerre ao sinal de fadiga.", "measure": "Registre orientação visual sem interpretar como teste diagnóstico.", "image": "ilustracoes/sensoriais/atividade-036.svg"}, "39": {"title": "Brinquedos com sons suaves", "prep": "Selecione dois brinquedos com sons suaves e controle de volume.", "do": "Apresente um som breve e aguarde; ofereça escolha ou oportunidade de acioná-lo.", "finish": "Intercale silêncio e som, respeitando desconforto.", "measure": "Registre preferência e participação voluntária.", "image": "ilustracoes/sensoriais/atividade-039.svg"}, "45": {"title": "Texturas em brinquedos", "prep": "Separe dois brinquedos grandes com superfícies distintas.", "do": "Demonstre como explorar com mãos ou observar de perto.", "finish": "Permita troca e repetição, sem exigir tocar na textura menos preferida.", "measure": "Registre escolhas e formas de exploração.", "image": "ilustracoes/sensoriais/atividade-045.svg"}, "52": {"title": "Caminho de texturas opcional", "prep": "Fixe tapetes antiderrapantes e mantenha rota lisa alternativa.", "do": "Mostre o percurso e permita passar calçado, descalço ou apenas observar.", "finish": "Convide a escolher a próxima superfície ou terminar quando quiser.", "measure": "Registre superfície escolhida, equilíbrio e conforto.", "image": "ilustracoes/sensoriais/atividade-052.svg"}, "57": {"title": "Brincar com água em recipiente", "prep": "Use recipiente raso sobre superfície estável, com supervisão contínua.", "do": "Demonstre transferir água com copo grande ou colher.", "finish": "Ofereça alternativa seca ou ferramenta para evitar molhar as mãos.", "measure": "Registre iniciativa, coordenação e participação.", "image": "ilustracoes/sensoriais/atividade-057.svg"}, "60": {"title": "Caixa de descobertas táteis", "prep": "Monte caixa aberta com objetos grandes de texturas conhecidas.", "do": "Convide a olhar e escolher um objeto; depois explore com mão ou ferramenta.", "finish": "Nomeie propriedades como macio ou áspero, sem exigir adivinhar pelo toque.", "measure": "Registre escolhas, linguagem funcional e tolerância.", "image": "ilustracoes/sensoriais/atividade-060.svg"}, "66": {"title": "Escolha de sons agradáveis", "prep": "Separe dois instrumentos suaves e possibilidade de silêncio.", "do": "Demonstre som breve de cada um, perguntando qual prefere.", "finish": "Deixe controlar início e fim; varie apenas com consentimento.", "measure": "Registre escolha e comunicação de parar.", "image": "ilustracoes/sensoriais/atividade-066.svg"}, "72": {"title": "Cantinho de pausa escolhido", "prep": "Escolha com a criança um local acessível, não isolado e nunca punitivo.", "do": "Disponha opções de conforto como cadeira, livro ou fone de redução de ruído.", "finish": "Pratique pedir pausa e retornar à atividade quando pronta.", "measure": "Registre iniciativa de solicitar pausa e retorno voluntário.", "image": "ilustracoes/sensoriais/atividade-072.svg"}, "77": {"title": "Experimentar ferramentas de pintura", "prep": "Organize pincel, rolinho, esponja e tinta lavável.", "do": "Demonstre uma marca com cada ferramenta e ofereça escolha.", "finish": "Experimente uma mudança por vez, sem obrigar contato com tinta.", "measure": "Registre ferramenta preferida, preensão e autonomia.", "image": "ilustracoes/sensoriais/atividade-077.svg"}, "83": {"title": "Identificar ambiente favorável", "prep": "Prepare imagens de sala silenciosa e sala movimentada, com escala visual.", "do": "Peça à criança que indique qual contexto favorece sua participação.", "finish": "Teste um ajuste ambiental escolhido e compare a participação.", "measure": "Registre ajuste testado e relato da criança.", "image": "ilustracoes/sensoriais/atividade-083.svg"}, "93": {"title": "Autodefesa sensorial na escola", "prep": "Prepare cartões de comunicação e exemplos reais de situações escolares.", "do": "Ensaie pedido respeitoso de pausa, mudança de lugar ou redução de ruído.", "finish": "Combine com a escola como atender à solicitação sem punição.", "measure": "Registre solicitação funcional e resposta do ambiente.", "image": "ilustracoes/sensoriais/atividade-093.svg"}};
function sensoryDetails58(a){
 const c=sensorySpecific[String(a.id)];
 if(!c)return sensoryDetails(a);
 return `<div class="sensory-detail">
 <img class="sensory-illustration" src="${c.image}" alt="Diagrama didático de três etapas para ${esc(a.title)}" loading="lazy">
 <p><b>Objetivo:</b> favorecer participação funcional e voluntária em ${esc(a.title).toLowerCase()}, respeitando perfil individual.</p>
 <p><b>Materiais:</b> ${esc(a.materials)}.</p>
 <p><b>1. Preparação:</b> ${esc(c.prep)}</p>
 <p><b>2. Execução:</b> ${esc(c.do)}</p>
 <p><b>3. Encerramento:</b> ${esc(c.finish)}</p>
 <p><b>Exemplo de adaptação:</b> ofereça alternativa de observar, usar ferramenta intermediária ou escolher intensidade e duração. Quando houver limitação motora, estabilize materiais e ajuste postura com avaliação individual; use comunicação alternativa se necessário.</p>
 <p><b>Indicador observável:</b> ${esc(c.measure)} Anote nível de ajuda, iniciativa e conforto.</p>
 <p><b>Cuidados:</b> ${esc(a.care)}. Não forçar contato, não interpretar reação isolada como diagnóstico e interromper diante de sofrimento.</p>
 <p class="muted"><b>Evidência:</b> proposta de atividade clínica ilustrativa; não há aqui alegação de eficácia específica demonstrada para esta atividade. Planejamento e adaptação dependem de avaliação do TO.</p></div>`;
}


