function sensoryDetails59(a){
 if(a.domain==='Sensorial')return sensoryDetails58(a);
 const c=library59[String(a.id)];if(!c)return sensoryDetails(a);
 return `<div class="sensory-detail"><img class="sensory-illustration" src="${c.image}" alt="Esquema de três etapas da atividade ${esc(a.title)}" loading="lazy">
 <p><b>Objetivo funcional:</b> ${esc(a.metric)}.</p>
 <p><b>1. Preparar:</b> ${esc(c.prep)}</p>
 <p><b>2. Demonstrar e praticar:</b> ${esc(c.demo)}</p>
 <p><b>3. Encerrar e observar:</b> ${esc(c.finish)}</p>
 <p><b>Adaptação individual:</b> ajuste posição, suporte, tamanho dos materiais, comunicação e número de tentativas conforme avaliação. Permita escolhas e interrupção; não imponha contato físico ou desempenho.</p>
 <p><b>Registro mensurável:</b> ${esc(c.metric)}</p>
 <p><b>Cuidados específicos:</b> ${esc(c.care)}.</p>
 <p class="muted"><b>Nota clínica:</b> sugestão prática para revisão profissional; não é protocolo validado nem substitui avaliação individual. O esquema apresenta as etapas, não a postura ou técnica anatômica.</p></div>`;
}

const sensoryArt={
'Sensorial':'sensorial','Motor global':'motor-global','Motor fino':'motor-fino',
'Brincar e interação':'brincar-e-interacao','AVDs':'avds','Planejamento motor':'planejamento-motor',
'Coordenação bilateral':'coordenacao-bilateral','Participação escolar':'participacao-escolar','Cognição':'cognicao'
};
function sensoryDetails(a){
 const title=esc(a.title),material=esc(a.materials),step=esc(a.steps),metric=esc(a.metric),care=esc(a.care);
 return `<div class="sensory-detail"><img class="sensory-illustration" src="ilustracoes/${sensoryArt[a.domain]||'sensorial'}.svg" alt="Ilustração didática esquemática da área ${esc(a.domain)}; não representa técnica específica" loading="lazy">
 <div class="detail-grid"><div><b>🎯 Objetivo funcional</b><p>Promover participação voluntária na atividade “${title}”, com apoio proporcional às habilidades da criança e observação de sua resposta funcional.</p></div><div><b>🧰 Materiais</b><p>${material}.</p></div></div>
 <b>🏠 Preparação do ambiente</b><p>Escolha um local seguro, acessível e com estímulos ajustáveis. Deixe ${material.toLowerCase()} ao alcance do profissional. Explique a proposta em linguagem, imagens ou comunicação alternativa adequadas e ofereça à criança a possibilidade de aceitar, modificar ou interromper.</p>
 <b>👣 Passo a passo — exemplo de sessão</b>
 <ol><li><b>Apresentar:</b> mostre os materiais e dê tempo para a criança observar ou escolher, sem exigir contato imediato.</li>
 <li><b>Demonstrar:</b> o terapeuta realiza uma demonstração breve: ${step}.</li>
 <li><b>Experimentar:</b> convide a criança a participar com o nível de ajuda necessário; aceite aproximação parcial e escolha de ferramentas alternativas.</li>
 <li><b>Variar:</b> simplifique a tarefa (menos etapas, maior apoio ou materiais maiores) ou acrescente uma etapa quando houver conforto e participação.</li>
 <li><b>Encerrar e registrar:</b> finalize de modo previsível, observe preferências, sinais de desconforto, ajuda oferecida e resposta funcional.</li></ol>
 <b>🧩 Adaptações concretas</b><p><b>Motricidade/postura:</b> estabilize materiais e use apoio postural individualizado; <b>comunicação:</b> ofereça escolhas visuais ou comunicação alternativa; <b>sensorial:</b> ajuste intensidade, duração e contato, sem exposição forçada; <b>atenção:</b> divida a tarefa em etapas curtas com pausas.</p>
 <b>📈 Indicadores de evolução</b><p>${metric}. Registre data, tempo ou número de tentativas, nível de ajuda (independente, verbal, gestual ou físico), iniciativa e conforto; compare sempre em contexto semelhante.</p>
 <b>⚠️ Precauções</b><p>${care}. Interrompa diante de dor, fadiga importante, sofrimento ou sinais de risco; avalie encaminhamento interdisciplinar quando indicado.</p>
 <b>👪 Possível continuidade em casa</b><p>Quando seguro e combinado com a família, repetir uma versão breve usando materiais cotidianos, priorizando brincar, autonomia e escolha. Não transformar a proposta em obrigação.</p>
 <p class="muted"><b>Evidência:</b> exemplo de atividade funcional baseada em raciocínio terapêutico; não é um protocolo cuja eficácia individual foi demonstrada. A indicação depende de avaliação profissional.</p></div>`;
}

