function renderSensory(){
app.innerHTML=`<section><h2>Desenvolvimento neuropsicomotor e estimulação sensorial</h2><p class="muted">Biblioteca com 100 propostas funcionais organizadas por faixa etária, diagnóstico informado e domínio. A idade é referência de organização, não limite rígido; habilidades, contexto, preferências e avaliação individual prevalecem. Nenhuma proposta constitui protocolo individual validado.</p>
<label>Paciente fictício</label><select id="ssPatient" onchange="sensoryRefresh()"><option value="">Selecione</option>${patients.map(p=>`<option value="${esc(p.code)}">${esc(p.code)}</option>`).join('')}</select>
<label>Faixa etária de referência</label><select id="ssAge" onchange="sensoryRefresh()">${ages.map((a,i)=>`<option value="${i}">${esc(a)}</option>`).join('')}</select>
<label>Diagnóstico informado (opcional, não é inferido)</label><select id="ssDx" onchange="sensoryRefresh()">${sensoryDx.map(d=>`<option>${esc(d)}</option>`).join('')}</select>
<label>Outros diagnósticos / observações (opcional)</label><input id="ssDxOther" placeholder="Não insira dados reais identificáveis">
<label>Área do desenvolvimento</label><select id="ssDomain" onchange="sensoryRefresh()">${sensoryDomains.map(d=>`<option>${esc(d)}</option>`).join('')}</select>
<label>Necessidade funcional prioritária</label><textarea id="ssNeed" placeholder="Ex.: explorar materiais de modo voluntário e ampliar participação em brincadeiras"></textarea>
<label>Precauções e adaptações individuais</label><textarea id="ssCare" placeholder="Ex.: apoio postural, comunicação alternativa, aversões, risco de queda, fadiga"></textarea>
<p class="alert">Triagem clínica necessária: dor, crises epilépticas, limitações posturais, risco de queda, alterações de deglutição e sofrimento intenso podem exigir adaptação ou avaliação interdisciplinar. Não impor estímulos sensoriais, contato físico ou contenção.</p>
<div id="ssResults"></div>
<label>Meta mensurável e contexto</label><textarea id="ssTarget" placeholder="Ex.: participar voluntariamente de 2 brincadeiras com materiais escolhidos, por 5 minutos, com apoio verbal, em 4 semanas"></textarea>
<label>Frequência / duração planejada</label><input id="ssFrequency" placeholder="Ex.: semanal, 30 minutos">
<label>Critério de reavaliação</label><textarea id="ssMeasure" placeholder="Ex.: participação, autonomia, nível de ajuda e sinais de desconforto"></textarea>
<button onclick="sensorySave()">Salvar plano selecionado</button></section>
<section><h3>Planos de desenvolvimento salvos (${sensoryPlans.length})</h3>${sensoryPlans.map((r,i)=>`<div class="activity"><b>${esc(r.code)} — ${esc(r.date)}</b><p>${esc(ages[r.age]||'Faixa não definida')} • ${esc(r.dx)} • ${r.activities.length} atividades</p><button onclick="sensoryPrint(${i})">Imprimir / PDF</button></div>`).join('')||'<p class="muted">Nenhum plano registrado.</p>'}</section>
<section><h3>Base clínica e evidências</h3><p class="muted">As propostas são exemplos de atividades ocupacionais e de brincadeira, não protocolos de eficácia individual demonstrada. Para planejar intervenções, priorize participação e metas funcionais, orientação familiar, acessibilidade e monitoramento. Intervenções especializadas de integração sensorial requerem formação, avaliação e fidelidade ao modelo; não equivalem a oferecer estímulos indiscriminadamente.</p><p><a href="https://www.who.int/publications/i/item/9789241515487" target="_blank" rel="noopener">OMS — Care for Child Development</a></p><p><a href="https://www.cdc.gov/act-early/milestones/index.html" target="_blank" rel="noopener">CDC — Marcos do desenvolvimento</a></p><p class="muted">Os links são materiais gerais de referência; não validam isoladamente cada atividade.</p></section>`;
sensoryRefresh();
}
function sensoryRefresh(){
let code=val('ssPatient'),p=patients.find(x=>x.code===code);
if(p&&p.age){let ix=ages.indexOf(p.age);if(ix>=0&&document.activeElement?.id==='ssPatient')document.getElementById('ssAge').value=ix}
let age=Number(val('ssAge')),domain=val('ssDomain'),dx=val('ssDx');
sensoryCurrent=sensoryCatalog.filter(a=>a.age===age&&(domain==='Todos'||a.domain===domain));
document.getElementById('ssResults').innerHTML=`<h3>${sensoryCurrent.length} atividades sugeridas para revisão</h3><p class="muted">Filtro por diagnóstico: ${esc(dx)}. O diagnóstico é documentado, mas não altera automaticamente as atividades sem avaliação funcional. Selecione somente propostas adequadas ao perfil da criança.</p>`+sensoryCurrent.map(a=>`<div class="activity"><label><input style="width:auto" type="checkbox" id="ssAct${a.id}"> ${esc(a.title)} <small>(${esc(a.domain)})</small></label><p><b>Materiais:</b> ${esc(a.materials)}</p><p><b>Passo a passo:</b> ${esc(a.steps)}</p><p><b>Indicador:</b> ${esc(a.metric)}</p><p><b>Cuidados:</b> ${esc(a.care)}</p><details><summary>📖 Abrir ficha detalhada e ilustração</summary>${sensoryDetails59(a)}</details></div>`).join('')+'<p class="muted">Nenhuma atividade é selecionada automaticamente; o TO deve revisar e aprovar.</p>';
}
function sensorySave(){
let code=val('ssPatient'),target=val('ssTarget').trim();
if(!code||!target)return alert('Selecione um paciente fictício e registre uma meta mensurável.');
let chosen=sensoryCurrent.filter(a=>document.getElementById('ssAct'+a.id)?.checked);
if(!chosen.length)return alert('Selecione ao menos uma atividade após revisão clínica.');
let r={code,date:new Date().toISOString().slice(0,10),age:Number(val('ssAge')),dx:val('ssDx'),dxOther:val('ssDxOther'),domain:val('ssDomain'),need:val('ssNeed'),care:val('ssCare'),target,frequency:val('ssFrequency'),measure:val('ssMeasure'),activities:chosen};
sensoryPlans.unshift(r);localStorage.setItem('tk_sensory_plans_v55',JSON.stringify(sensoryPlans));renderSensory();alert('Plano salvo no navegador. Faça backup para preservar o registro.');
}
function sensoryPrint(i){
let r=sensoryPlans[i];if(!r)return;let w=window.open('','_blank');if(!w)return alert('Permita pop-ups para gerar PDF.');
let t=x=>esc(x||'—');
w.document.write('<!doctype html><html lang="pt-BR"><meta charset="utf-8"><title>Plano sensoriomotor</title><style>body{font:14px Arial;max-width:820px;margin:35px auto;line-height:1.5}h1{color:#164b4c}section{padding:8px 0;border-bottom:1px solid #ccc}</style><h1>TO Kids PRO 5.9 — Plano sensoriomotor</h1><p>Paciente: '+t(r.code)+' | Data: '+t(r.date)+' | Faixa: '+t(ages[r.age])+'</p><section><b>Diagnóstico informado:</b> '+t(r.dx)+' — '+t(r.dxOther)+'</section><section><b>Necessidade funcional:</b> '+t(r.need)+'</section><section><b>Meta:</b> '+t(r.target)+'</section><section><b>Frequência:</b> '+t(r.frequency)+'</section><section><b>Reavaliação:</b> '+t(r.measure)+'</section><section><b>Precauções:</b> '+t(r.care)+'</section><h2>Atividades aprovadas</h2>'+r.activities.map(a=>'<section><b>'+t(a.title)+'</b> ('+t(a.domain)+')<p><b>Materiais:</b> '+t(a.materials)+'</p><p><b>Execução:</b> '+t(a.steps)+'</p><p><b>Indicador:</b> '+t(a.metric)+'</p><p><b>Cuidados:</b> '+t(a.care)+'</p></section>').join('')+'<p>Plano observacional individualizado, não diagnóstico. Terapeuta responsável: __________________</p></html>');w.document.close();w.focus();setTimeout(()=>w.print(),300);
}

