const foodTherapyActivities=[["Exposição repetida sem pressão", "2–12 anos", "Promissora; evidência de programas, não desta atividade isolada", "Exposição repetida e familiarização", "Alimento-alvo seguro, prato e registro", "Oferecer presença do alimento em porção pequena; permitir observar, aproximar e escolher explorar sem exigência de provar. Repetir em diferentes dias.", "Registrar presença tolerada, aproximações espontâneas e ingestão real, separadamente."], ["Modelagem em refeição compartilhada", "1–12 anos", "Apoio em intervenções estruturadas com cuidadores", "Modelagem e participação", "Alimentos seguros e alimento-alvo, mesa acessível", "Adulto realiza refeição de modo natural e modela exploração; criança escolhe se participa; evitar barganhas e coerção.", "Registrar frequência de participação e alimentos consumidos em refeições reais."], ["Treinamento parental: rotina responsiva", "6 meses–12 anos", "Melhor respaldo para programas multicomponentes, especialmente em autismo", "Treinamento de cuidadores", "Diário alimentar e rotina doméstica", "Definir horários previsíveis, oferta sem pressão, atenção aos sinais de fome/saciedade e metas acordadas com a família.", "Registrar frequência de conflitos, duração e participação nas refeições."], ["Ponte entre alimentos semelhantes", "2–12 anos", "Limitada para food chaining isolado", "Encadeamento alimentar", "Um alimento aceito e variações próximas", "Escolher uma mudança por vez em marca, formato ou preparo; apresentar ao lado do alimento seguro, sem retirar opções aceitas.", "Registrar novas variações realmente consumidas em mais de uma ocasião."], ["Preparação culinária participativa", "3–12 anos", "Complementar; eficácia isolada não estabelecida", "Participação ocupacional e exposição", "Utensílios adequados à idade e alimentos seguros", "Convidar a lavar, cortar com utensílio seguro, misturar e servir; permitir não provar.", "Registrar tolerância, autonomia, participação e ingestão separadamente."], ["Exploração com utensílios", "1–8 anos", "Complementar; eficácia isolada não estabelecida", "Exploração sensorial gradual", "Colher, pinça infantil e alimento de textura segura", "Manipular alimento com utensílio antes de eventual contato manual, respeitando limites sensoriais.", "Registrar etapa de aproximação voluntária e desconforto."], ["Escolhas alimentares estruturadas", "2–12 anos", "Estratégia clínica complementar; evidência isolada limitada", "Autonomia e suporte à participação", "Duas opções adequadas e seguras", "Oferecer escolha real entre duas opções sem exigir ingestão; combinar com rotina previsível.", "Registrar escolhas espontâneas e participação na refeição."], ["Ajuste postural para refeições", "0–12 anos", "Indicação funcional individualizada; efeito isolado na seletividade não comprovado", "Posicionamento e função", "Cadeira estável, apoio dos pés e utensílios", "Avaliar estabilidade de tronco e pés, altura da mesa e alcance; adaptar com profissional habilitado.", "Registrar estabilidade, fadiga, autonomia e sinais de segurança."], ["Graduação de textura com segurança", "6 meses–12 anos", "Depende da condição clínica; não aplicar sem triagem de deglutição", "Adaptação de demanda e segurança", "Texturas apropriadas ao desenvolvimento e avaliação", "Após verificar habilidades orais e riscos, oferecer progressão individualizada com equipe; não avançar diante de tosse ou engasgo.", "Registrar segurança, aceitação e consistências toleradas."], ["Planejamento de lanche pela criança", "6–12 anos", "Complementar; eficácia isolada na seletividade não estabelecida", "Participação e autonomia", "Cartões de alimentos, lista e utensílios", "Planejar lanche com opções aceitas e possibilidade de explorar novidade, respeitando preferências e necessidades nutricionais.", "Registrar autonomia no planejamento e consumo real."], ["Diário de repertório alimentar", "0–12 anos", "Ferramenta de mensuração; não é tratamento", "Monitoramento de resultados", "Ficha de registro", "Registrar alimentos, marcas, apresentações, quantidades aproximadas e contexto ao longo de dias.", "Contar alimentos distintos consumidos e manutenção ao longo do tempo."], ["Metas familiares mensuráveis", "0–12 anos", "Componente de programas estruturados; não é técnica isolada", "Planejamento centrado na família", "Ficha de metas e rotina", "Definir uma meta de participação observável com prazo e apoio necessário; revisar semanalmente.", "Comparar linha de base, evolução e generalização em casa."]];
const foodEvidenceRefs=[["Johnson et al., 2019 — Parent Training for Feeding Problems in Children With Autism Spectrum Disorder", "https://pubmed.ncbi.nlm.nih.gov/30101320/"], ["Sharp et al., 2019 — The Autism MEAL Plan", "https://pubmed.ncbi.nlm.nih.gov/31056202/"], ["Akyurek e Senturk, 2025 — revisão sistemática", "https://pubmed.ncbi.nlm.nih.gov/40850595/"]];
function renderFoodActivities(){let items=foodTherapyActivities;app.innerHTML=`<section><h2>Biblioteca clínica • seletividade alimentar</h2><p class="muted">Atividades inspiradas em princípios pesquisados. As propostas individuais abaixo NÃO são protocolos validados nem garantem eficácia. Evite coerção e investigue disfagia, dor, perda ponderal e desidratação.</p><label>Filtrar por faixa ou termo</label><input id="foodActivityFilter" placeholder="Ex.: 3–12, exposição, postura" oninput="filterFoodActivities()"><div id="foodActivityResults"></div></section><section><h3>Referências científicas</h3>${foodEvidenceRefs.map(r=>`<p><a href="${r[1]}" target="_blank" rel="noopener noreferrer">${esc(r[0])}</a></p>`).join('')}<p class="muted">A evidência é principalmente de intervenções multicomponentes; não atribua resultados de um programa a cada atividade isolada. Avalie contexto, segurança, alimentação e participação com equipe interdisciplinar.</p></section>`;filterFoodActivities()}
function filterFoodActivities(){let q=(document.getElementById('foodActivityFilter')?.value||'').toLowerCase();let matches=foodTherapyActivities.filter(a=>a.join(' ').toLowerCase().includes(q));document.getElementById('foodActivityResults').innerHTML=matches.map((a,i)=>`<details class="activity"><summary><b>${esc(a[0])}</b> <small>• ${esc(a[1])}</small></summary><p><b>Força da evidência:</b> ${esc(a[2])}</p><p><b>Princípio:</b> ${esc(a[3])}</p><p><b>Materiais:</b> ${esc(a[4])}</p><p><b>Passo a passo:</b> ${esc(a[5])}</p><p><b>Indicador de evolução:</b> ${esc(a[6])}</p></details>`).join('')||'<p>Nenhuma atividade encontrada.</p>'}
